def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create a grid with all zeros
    grid = [[0] * N for _ in range(N)]

    # Populate the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize a DP table to store the maximum values
    dp = [[[0, 0] for _ in range(N)] for _ in range(N)]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                dp[i][j] = [grid[0][0], 0]
                continue
            if i == 0:
                dp[i][j] = [dp[i][j-1][0] + grid[i][j], 0]
            elif j == 0:
                dp[i][j] = [dp[i-1][j][0] + grid[i][j], 0]
            else:
                dp[i][j] = [
                    max(dp[i-1][j][0], dp[i][j-1][0]) + grid[i][j],
                    max(dp[i-1][j][1], dp[i][j-1][1], dp[i-1][j-1][0], dp[i-1][j-1][1]) + grid[i][j]
                ]

    # Return the maximum sum of values collected on the two paths
    return max(dp[N-1][N-1])

