def max_product(num_str: str, N: int, K: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def dp(i, k):
        if k == 0:
            return int(num_str[i:])
        max_product = 0
        for j in range(i + 1, N - k + 1):
            max_product = max(max_product, int(num_str[i:j]) * dp(j, k - 1))
        return max_product

    return dp(0, K)

