def count_passing_ways(n: int, m: int) -> int:
    MOD = 10**9 + 7
    if n == 1 and m == 0:
        return 1
    if m == 0:
        return 0

    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][1] = 1
    dp[0][2] = 1

    for i in range(1, n):
        dp[i][1] = 2
        dp[i][2] = 2

    for j in range(3, m + 1):
        for i in range(1, n):
            dp[i][j] = (dp[i-1][j-1] + dp[i+1][j-1]) % MOD

    return dp[0][m]

def max_energy(beads):
    n = len(beads)
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for start in range(n - length + 1):
            end = (start + length - 1) % n
            for i in range(start, end):
                dp[start][end] = max(dp[start][end], beads[start] * beads[i + 1] * beads[end] + dp[start][i] + dp[i + 1][end])

    return dp[0][n - 1]

