def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff == 0:
            continue
        sign = '-' if coeff < 0 else ''
        abs_coeff = abs(coeff)
        if abs_coeff == 1 and i != 0:
            abs_coeff = ''
        else:
            abs_coeff = str(abs_coeff)

        if i == 0:
            term = f"{sign}{abs_coeff}"
        elif i == 1:
            term = f"{sign}{abs_coeff}x"
        else:
            term = f"{sign}{abs_coeff}x^{i}"

        terms.append(term)

    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping and mapping[e] != o:
            return "Failed"
        mapping[e] = o

    if len(mapping) != len(set(mapping.values())):
        return "Failed"

    decoded = ""
    for char in message:
        if char in mapping:
            decoded += mapping[char]
        else:
            return "Failed"

    return decoded

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
        return 0
    if k == 1:
        return 1
    if k == n:
        return 1
    return sum(count_partitions(n-i, k-1, i) for i in range(x, n//k + 1))

def count_coprime_pairs(x0: int, y0: int) -> int:
    from math import gcd

    count = 0
    quotient = y0 // x0

    for a in range(1, quotient + 1):
        if quotient % a == 0:
            b = quotient // a
            if gcd(a, b) == 1:
                count += 2 if a != b else 1

    return count

def is_prime(num: int) -> bool:
    """
    Determine whether a given integer is a prime number.

    Args:
    num (int): The integer to check for primality.

    Returns:
    bool: True if `num` is a prime number, False otherwise.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque

    visited = set()
    queue = deque([n])

    while queue:
        current = queue.popleft()
        if current not in visited:
            visited.add(current)

            current_str = str(current)
            for i in range(len(current_str)):
                for x, y in rules:
                    if int(current_str[i]) == x:
                        new_number = int(current_str[:i] + str(y) + current_str[i+1:])
                        queue.append(new_number)

    return len(visited)

