def jinjin_savings_plan(budgets: List[int]) -> int:
    total_savings = 0
    monthly_pocket_money = 300
    interest_rate = 0.20

    for month, budget in enumerate(budgets, start=1):
        remaining_money = monthly_pocket_money - budget
        if remaining_money >= 100:
            savings = remaining_money - 100
            total_savings += savings
        else:
            return -month

    total_savings_at_end_of_year = total_savings * (1 + interest_rate)
    return int(total_savings_at_end_of_year)

def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 2:
        return 0

    def find_max_length(heights, is_increasing):
        dp = [1] * n
        for i in range(1, n):
            if (is_increasing and heights[i] > heights[i - 1]) or (not is_increasing and heights[i] < heights[i - 1]):
                dp[i] = dp[i - 1] + 1
        return max(dp)

    increasing = find_max_length(heights, True)
    decreasing = find_max_length(heights[::-1], True)
    max_choir = max(increasing, decreasing) - 1

    return n - max_choir

def hanoi_double_iterative(n: int) -> int:
    # The number of moves required for n pairs of discs in the double-disc Hanoi Towers problem
    return 2 ** (2 * n) - 2
